import java.sql.*;
import java.util.UUID;

public class JdbcTasks {
    public int createUser(Connection conn, String email, String name) throws SQLException {
        PreparedStatement ps = conn.prepareStatement(
            "INSERT INTO users (email, name) VALUES (?, ?)",
            Statement.RETURN_GENERATED_KEYS);
        ps.setString(1, email);
        ps.setString(2, name);
        ps.executeUpdate();
        ResultSet rs = ps.getGeneratedKeys();
        rs.next();
        int id = rs.getInt(1);
        rs.close();
        ps.close();
        return id;
    }

    public void deleteUser(Connection conn, int userId) throws SQLException {
        PreparedStatement ps = conn.prepareStatement("DELETE FROM users WHERE id = ?");
        ps.setInt(1, userId);
        ps.executeUpdate();
        ps.close();
    }

    public int cleanupAndCreate(Connection conn, String name) throws SQLException {
        Statement stmt = conn.createStatement();
        stmt.execute("DELETE FROM users");
        stmt.close();
        String email = "test_" + UUID.randomUUID() + "@test.com";
        return createUser(conn, email, name);
    }
}

